class Solution {
    private static class Entry {
        TreeNode node;
        long index;

        Entry(TreeNode node, long index) {
            this.node = node;
            this.index = index;
        }
    }

    public int widthOfBinaryTree(TreeNode root) {
        if (root == null) {
            return 0;
        }

        java.util.ArrayDeque<Entry> queue = new java.util.ArrayDeque<>();
        queue.offer(new Entry(root, 0L));
        int best = 0;

        while (!queue.isEmpty()) {
            int size = queue.size();
            long levelBase = queue.peekFirst().index;
            long first = 0;
            long last = 0;

            for (int i = 0; i < size; i++) {
                Entry entry = queue.poll();
                TreeNode node = entry.node;
                long normalized = entry.index - levelBase;
                if (i == 0) {
                    first = normalized;
                }
                if (i == size - 1) {
                    last = normalized;
                }
                if (node.left != null) {
                    queue.offer(new Entry(node.left, normalized * 2));
                }
                if (node.right != null) {
                    queue.offer(new Entry(node.right, normalized * 2 + 1));
                }
            }

            best = Math.max(best, (int) (last - first + 1));
        }

        return best;
    }
}

class Solution {
    private final java.util.List<Long> firstIndexAtDepth = new java.util.ArrayList<>();
    private int answer;

    public int widthOfBinaryTree(TreeNode root) {
        firstIndexAtDepth.clear();
        answer = 0;
        dfs(root, 0, 0L);
        return answer;
    }

    private void dfs(TreeNode node, int depth, long index) {
        if (node == null) {
            return;
        }
        if (depth == firstIndexAtDepth.size()) {
            firstIndexAtDepth.add(index);
        }

        long normalized = index - firstIndexAtDepth.get(depth);
        answer = Math.max(answer, (int) normalized + 1);
        dfs(node.left, depth + 1, normalized * 2);
        dfs(node.right, depth + 1, normalized * 2 + 1);
    }
}

class Solution {
    private static class Frame {
        TreeNode node;
        int depth;
        long index;

        Frame(TreeNode node, int depth, long index) {
            this.node = node;
            this.depth = depth;
            this.index = index;
        }
    }

    public int widthOfBinaryTree(TreeNode root) {
        if (root == null) {
            return 0;
        }

        java.util.ArrayList<Long> firstIndexAtDepth = new java.util.ArrayList<>();
        java.util.ArrayDeque<Frame> stack = new java.util.ArrayDeque<>();
        stack.push(new Frame(root, 0, 0L));
        int best = 0;

        while (!stack.isEmpty()) {
            Frame frame = stack.pop();
            if (frame.depth == firstIndexAtDepth.size()) {
                firstIndexAtDepth.add(frame.index);
            }
            long normalized = frame.index - firstIndexAtDepth.get(frame.depth);
            best = Math.max(best, (int) normalized + 1);

            if (frame.node.right != null) {
                stack.push(new Frame(frame.node.right, frame.depth + 1, normalized * 2 + 1));
            }
            if (frame.node.left != null) {
                stack.push(new Frame(frame.node.left, frame.depth + 1, normalized * 2));
            }
        }

        return best;
    }
}

class Solution {
    public int widthOfBinaryTree(TreeNode root) {
        if (root == null) {
            return 0;
        }

        java.util.List<TreeNode> levelNodes = new java.util.ArrayList<>();
        java.util.List<Long> levelIndices = new java.util.ArrayList<>();
        levelNodes.add(root);
        levelIndices.add(0L);
        int best = 1;

        while (!levelNodes.isEmpty()) {
            long first = levelIndices.get(0);
            long last = levelIndices.get(levelIndices.size() - 1);
            best = Math.max(best, (int) (last - first + 1));

            java.util.List<TreeNode> nextNodes = new java.util.ArrayList<>();
            java.util.List<Long> nextIndices = new java.util.ArrayList<>();
            for (int i = 0; i < levelNodes.size(); i++) {
                TreeNode node = levelNodes.get(i);
                long normalized = levelIndices.get(i) - first;
                if (node.left != null) {
                    nextNodes.add(node.left);
                    nextIndices.add(normalized * 2);
                }
                if (node.right != null) {
                    nextNodes.add(node.right);
                    nextIndices.add(normalized * 2 + 1);
                }
            }
            levelNodes = nextNodes;
            levelIndices = nextIndices;
        }

        return best;
    }
}
